Minimal and flexible Node.js web application framework.

```javascript
const express = require('express');
const app = express();

app.get('/', (req, res) => {
  res.send('Hello World');
});

app.listen(3000);
```

Functions with access to request, response, and next function.

```javascript
app.use((req, res, next) => {
  console.log('middleware');
  next();
});
```

Response object for sending HTTP response.

```javascript
res.send('text');
res.json({ data: 'value' });
res.status(404).send('Not Found');
res.redirect('/home');
```

Defining application endpoints and their handlers.

```javascript
app.get('/users', (req, res) => res.json(users));
app.post('/users', (req, res) => res.json(newUser));
app.put('/users/:id', (req, res) => res.json(updatedUser));
app.delete('/users/:id', (req, res) => res.sendStatus(204));
```

Dynamic URL segments.

```javascript
app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  res.json({ userId });
});
```

URL parameters after `?`.

```javascript
// GET /search?q=express&page=2
app.get('/search', (req, res) => {
  console.log(req.query.q); // "express"
  console.log(req.query.page); // "2"
});
```

Middleware parsing JSON request bodies.

```javascript
app.use(express.json());

app.post('/data', (req, res) => {
  console.log(req.body); // parsed JSON
});
```

Serves static files.

```javascript
app.use(express.static('public'));
// serves files from /public directory
```

Passes control to next middleware.

```javascript
app.use((req, res, next) => {
  console.log('first');
  next(); // pass to next middleware
});
```

Middleware with 4 parameters for handling errors.

```javascript
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Error');
});
```

Modular route handlers.

```javascript
const router = express.Router();

router.get('/users', (req, res) => res.json(users));
router.post('/users', (req, res) => res.json(newUser));

app.use('/api', router);
```

Cross-Origin Resource Sharing. Use `cors` middleware.

```javascript
const cors = require('cors');
app.use(cors());
```

Limiting number of requests from client.

```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});

app.use('/api', limiter);
```

Security middleware setting HTTP headers.

```javascript
const helmet = require('helmet');
app.use(helmet());
```

HTTP request logger middleware.

```javascript
const morgan = require('morgan');
app.use(morgan('combined'));
```
